def wordBreakII(s, wordDict):
    word_set = set(wordDict)
    memo = {}
    def backtrack(start):
        if start in memo:
            return memo[start]
        if start == len(s):
            return ['']
        result = []
        for end in range(start + 1, len(s) + 1):
            if s[start:end] in word_set:
                for sub in backtrack(end):
                    result.append(s[start:end] + ('' if sub == '' else ' ' + sub))
        memo[start] = result
        return result
    return backtrack(0)

