from collections import Counter
import heapq

def isNStraightHand(hand, groupSize):
    if len(hand) % groupSize != 0:
        return False
    card_count = Counter(hand)
    min_heap = list(card_count.keys())
    heapq.heapify(min_heap)
    for _ in range(len(hand) // groupSize):
        for _ in range(groupSize):
            if not min_heap:
                return False
            card = heapq.heappop(min_heap)
            card_count[card] -= 1
            if card_count[card] > 0:
                heapq.heappush(min_heap, card)
        if min_heap:
            next_card = min_heap[0]
            if card_count[next_card] == 0:
                continue
            if card != next_card - 1:
                return False
    return True

