            heapq.heappush(heap, (lst.val, id(lst), lst))
    dummy = ListNode(0)
    current = dummy
    while heap:
        _, _, node = heapq.heappop(heap)
        current.next = node
        current = current.next
        if node.next:
            heapq.heappush(heap, (node.next.val, id(node.next), node.next))
