# Before: 2D DP (O(m*n) space)
def knapsack_2d(capacity, weights, values):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i-1] <= w:
                dp[i][w] = max(values[i-1] + dp[i-1][w-weights[i-1]], dp[i-1][w])
            else:
                dp[i][w] = dp[i-1][w]
    return dp[n][capacity]

# After: 1D DP (O(capacity) space)
def knapsack_1d(capacity, weights, values):
    dp = [0] * (capacity + 1)
    for i in range(len(weights)):
        # Iterate backwards to avoid using updated values
        for w in range(capacity, weights[i] - 1, -1):
            dp[w] = max(dp[w], values[i] + dp[w - weights[i]])
    return dp[capacity]

# Key: Iterate from right to left to avoid reusing updated values
print(knapsack_1d(5, [2, 3], [3, 4]))  # 7
