# Overlapping Subproblems: Same subproblems are solved multiple times
# Optimal Substructure: Optimal solution built from optimal solutions of subproblems

# Fibonacci has BOTH properties
def fib_naive(n):
    if n <= 1:
        return n
    return fib_naive(n-1) + fib_naive(n-2)  # Recomputes same values

# Memoization solves overlapping subproblems
def fib_memo(n, memo={}):
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fib_memo(n-1, memo) + fib_memo(n-2, memo)
    return memo[n]

# Coin change has both properties
def coinChange(coins, amount):
    # dp[i] = optimal solution for amount i (min coins)
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for coin in coins:
            if coin <= i:
                # Optimal substructure: dp[i] = 1 + dp[i - coin]
                dp[i] = min(dp[i], dp[i - coin] + 1)
    return dp[amount]
