def minPathSum(grid):
    if not grid or not grid[0]:
        return 0
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = grid[0][0]
    # First row: can only come from left
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + grid[0][j]
    # First column: can only come from top
    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + grid[i][0]
    # Rest: min of top or left
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]
    return dp[m-1][n-1]

print(minPathSum([[1, 3, 1], [1, 5, 1], [4, 2, 1]]))  # 7 (1+3+1+1+1)

# With obstacles (0 = blocked, 1 = walkable)
def minPathSumWithObstacles(grid):
    m, n = len(grid), len(grid[0])
    dp = [[float('inf')] * n for _ in range(m)]
    dp[0][0] = grid[0][0]
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:  # Obstacle
                dp[i][j] = float('inf')
            elif i == 0 and j > 0:
                dp[i][j] = dp[i][j-1] + grid[i][j]
            elif j == 0 and i > 0:
                dp[i][j] = dp[i-1][j] + grid[i][j]
            elif i > 0 and j > 0:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]
    return dp[m-1][n-1] if dp[m-1][n-1] != float('inf') else -1
